// Picks the next keyword from the backlog: status "ready", best priority
// first, then highest opportunity score. KEYWORD_OVERRIDE forces a keyword.
const cfg = $('Config').first().json;
const rows = $input.all().map((i) => i.json);

const override = String(cfg.KEYWORD_OVERRIDE || '').trim().toLowerCase();
const ready = rows.filter((r) =>
	override ? String(r.keyword).trim().toLowerCase() === override : String(r.status).trim().toLowerCase() === 'ready',
);

if (!ready.length) {
	// Nothing to write: stop quietly instead of failing the scheduled run.
	return [];
}

ready.sort(
	(a, b) =>
		(Number(a.priority) || 3) - (Number(b.priority) || 3) ||
		(Number(b.opportunity_score) || 0) - (Number(a.opportunity_score) || 0),
);

const pick = ready[0];
const split = (value) =>
	String(value || '')
		.split('|')
		.map((s) => s.trim())
		.filter(Boolean);

return [
	{
		json: {
			...pick,
			keyword: String(pick.keyword).trim(),
			questions: [...new Set([...split(pick.questions_to_answer), ...split(pick.people_also_ask)])],
			competitor_urls: split(pick.top_competitors),
			location_name: pick.location || cfg.LOCATION_NAME,
			language_name: pick.language || cfg.LANGUAGE,
		},
	},
];

// Builds the internal-link inventory from the site's sitemap(s): every
// public URL with its title and meta description, so Claude can only link to
// pages that really exist.
const cfg = $('Config').first().json;
const topic = $input.first().json;

const MAX_URLS = Number(cfg.MAX_SITEMAP_URLS) || 400;
const MAX_FETCH_TITLES = Number(cfg.MAX_PAGES_TO_READ) || 60;
const siteHost = new URL(cfg.SITE_URL).hostname.replace(/^www\./, '');
const EXCLUDE = /\/(tag|tags|category|author|page|feed|wp-json|cart|checkout|account|login|privacy|cookie|terms)(\/|$)|\.(jpg|jpeg|png|gif|webp|svg|pdf|xml)$/i;

const get = async (url) =>
	this.helpers.httpRequest({
		url,
		method: 'GET',
		timeout: 15000,
		headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BlogAutomationBot/1.0)' },
		returnFullResponse: false,
		json: false,
	});

const locs = (xml) => [...String(xml).matchAll(/<loc>\s*(?:<!\[CDATA\[)?(.*?)(?:\]\]>)?\s*<\/loc>/gi)].map((m) => m[1].trim());

const sitemapQueue = [cfg.SITEMAP_URL || new URL('/sitemap.xml', cfg.SITE_URL).href];
const seenSitemaps = new Set();
const pageUrls = new Set();

while (sitemapQueue.length && seenSitemaps.size < 25 && pageUrls.size < MAX_URLS) {
	const sitemapUrl = sitemapQueue.shift();
	if (seenSitemaps.has(sitemapUrl)) continue;
	seenSitemaps.add(sitemapUrl);
	let xml;
	try {
		xml = await get(sitemapUrl);
	} catch (error) {
		continue;
	}
	const isIndex = /<sitemapindex/i.test(xml);
	for (const loc of locs(xml)) {
		if (isIndex) sitemapQueue.push(loc);
		else pageUrls.add(loc);
	}
}

if (!pageUrls.size) {
	throw new Error(`No URLs found in sitemap ${sitemapQueue[0] || cfg.SITEMAP_URL}. Set SITEMAP_URL in Config.`);
}

const pages = [...pageUrls]
	.filter((u) => {
		try {
			return new URL(u).hostname.replace(/^www\./, '') === siteHost && !EXCLUDE.test(new URL(u).pathname);
		} catch (error) {
			return false;
		}
	})
	.slice(0, MAX_URLS)
	.map((url) => {
		const slug = new URL(url).pathname.replace(/\/$/, '').split('/').pop() || 'home';
		return { url, title: slug.replace(/[-_]+/g, ' '), description: '' };
	});

// Read the pages most related to the topic first so their real titles and
// descriptions are known. The rest keep a title derived from the slug.
const topicTokens = String(topic.keyword).toLowerCase().split(/\s+/).filter((t) => t.length >= 3);
const relatedness = (p) => topicTokens.filter((t) => p.url.toLowerCase().includes(t)).length;
const toRead = [...pages].sort((a, b) => relatedness(b) - relatedness(a)).slice(0, MAX_FETCH_TITLES);

const decode = (s) =>
	String(s || '')
		.replace(/&amp;/g, '&')
		.replace(/&quot;/g, '"')
		.replace(/&#0?39;|&apos;/g, "'")
		.replace(/&lt;/g, '<')
		.replace(/&gt;/g, '>')
		.replace(/\s+/g, ' ')
		.trim();

for (let i = 0; i < toRead.length; i += 6) {
	await Promise.all(
		toRead.slice(i, i + 6).map(async (page) => {
			try {
				const html = await get(page.url);
				const title = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i)?.[1];
				const description =
					html.match(/<meta[^>]+name=["']description["'][^>]+content=["']([^"']*)["']/i)?.[1] ||
					html.match(/<meta[^>]+content=["']([^"']*)["'][^>]+name=["']description["']/i)?.[1];
				if (title) page.title = decode(title);
				if (description) page.description = decode(description).slice(0, 200);
			} catch (error) {
				// Unreachable page: keep the slug-based title.
			}
		}),
	);
}

return [{ json: { ...topic, internal_pages: pages } }];

// Reads the pages that currently rank: their headings (what we must cover
// and beat) and the sources they cite (candidates for our external links).
const cfg = $('Config').first().json;
const topic = $('Crawl sitemap (internal links)').first().json;
const serp = $input.first().json.tasks?.[0]?.result?.[0]?.items || [];

const siteHost = new URL(cfg.SITE_URL).hostname.replace(/^www\./, '');
const hostOf = (url) => {
	try {
		return new URL(url).hostname.replace(/^www\./, '');
	} catch (error) {
		return '';
	}
};

const organic = serp
	.filter((i) => i.type === 'organic' && hostOf(i.url) !== siteHost)
	.slice(0, 10)
	.map((i) => ({ rank: i.rank_group, url: i.url, domain: hostOf(i.url), title: i.title, description: i.description || '' }));

const peopleAlsoAsk = serp
	.filter((i) => i.type === 'people_also_ask')
	.flatMap((i) => i.items || [])
	.map((q) => q.title)
	.filter(Boolean);

const competitorDomains = new Set(organic.map((o) => o.domain));
// Sites we never cite: social, UGC, aggregators, link shorteners, and the
// pages we are competing with.
const NEVER_CITE = /(facebook|instagram|twitter|x\.com|linkedin|pinterest|tiktok|youtube|reddit|quora|medium|amazon|bol\.com|bit\.ly|google\.|goo\.gl|t\.co|wa\.me)/i;
const AUTHORITY = /\.(gov|edu|ac\.[a-z]{2}|europa\.eu)$|(wikipedia\.org|who\.int|oecd\.org|cbs\.nl|rijksoverheid\.nl|kvk\.nl|belastingdienst\.nl|statista\.com|mckinsey\.com|gartner\.com|hbr\.org|forrester\.com|nature\.com|ncbi\.nlm\.nih\.gov|w3\.org|developer\.mozilla\.org|developers\.google\.com|github\.com)$/i;

const strip = (html) =>
	String(html)
		.replace(/<[^>]+>/g, ' ')
		.replace(/&nbsp;|&#160;/g, ' ')
		.replace(/&amp;/g, '&')
		.replace(/\s+/g, ' ')
		.trim();

const competitorPages = [];
const externalCandidates = new Map();

const pagesToRead = organic.slice(0, Number(cfg.COMPETITOR_PAGES_TO_READ) || 5);
await Promise.all(
	pagesToRead.map(async (page) => {
		let html = '';
		try {
			html = await this.helpers.httpRequest({
				url: page.url,
				timeout: 20000,
				json: false,
				headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BlogAutomationBot/1.0)' },
			});
		} catch (error) {
			competitorPages.push({ ...page, headings: [], word_count: null, note: 'could not be fetched' });
			return;
		}
		const body = String(html)
			.replace(/<script[\s\S]*?<\/script>/gi, '')
			.replace(/<style[\s\S]*?<\/style>/gi, '')
			.replace(/<(nav|header|footer|aside)[\s\S]*?<\/\1>/gi, '');
		const headings = [...body.matchAll(/<(h2|h3)[^>]*>([\s\S]*?)<\/\1>/gi)]
			.map((m) => `${m[1].toUpperCase()}: ${strip(m[2])}`)
			.filter((h) => h.length > 4)
			.slice(0, 30);
		const wordCount = strip(body).split(' ').length;

		for (const m of body.matchAll(/<a[^>]+href=["'](https?:\/\/[^"'#]+)["'][^>]*>([\s\S]*?)<\/a>/gi)) {
			const url = m[1];
			const domain = hostOf(url);
			if (!domain || domain === page.domain || domain === siteHost) continue;
			if (competitorDomains.has(domain) || NEVER_CITE.test(domain)) continue;
			const anchor = strip(m[2]).slice(0, 120);
			if (anchor.length < 3) continue;
			const existing = externalCandidates.get(url) || { url, domain, anchor, cited_by: 0, authority: AUTHORITY.test(domain) };
			existing.cited_by += 1;
			externalCandidates.set(url, existing);
		}

		competitorPages.push({ ...page, headings, word_count: wordCount });
	}),
);

// Authority sources and sources cited by several competitors first.
const externalSources = [...externalCandidates.values()]
	.sort((a, b) => Number(b.authority) - Number(a.authority) || b.cited_by - a.cited_by)
	.slice(0, 25);

const wordCounts = competitorPages.map((p) => p.word_count).filter(Boolean);
const medianWords = wordCounts.length ? wordCounts.sort((a, b) => a - b)[Math.floor(wordCounts.length / 2)] : null;

return [
	{
		json: {
			...topic,
			questions: [...new Set([...(topic.questions || []), ...peopleAlsoAsk])].slice(0, 12),
			serp_results: organic,
			competitor_pages: competitorPages.sort((a, b) => a.rank - b.rank),
			competitor_median_words: medianWords,
			external_sources: externalSources,
		},
	},
];

// Step 1 of writing: Claude plans the article (outline, link plan, diagrams)
// using only the research gathered so far.
const cfg = $('Config').first().json;
const r = $('Research competitors').first().json;

const internalPages = r.internal_pages
	.map((p) => `- ${p.url} | ${p.title}${p.description ? ` | ${p.description}` : ''}`)
	.join('\n');
const externalSources = r.external_sources
	.map((s) => `- ${s.url} | anchor used by competitors: "${s.anchor}" | cited by ${s.cited_by} | authority: ${s.authority}`)
	.join('\n');
const competitors = r.competitor_pages
	.map((p) => `#${p.rank} ${p.url} (${p.word_count ?? '?'} words)\n${p.headings.map((h) => `   ${h}`).join('\n')}`)
	.join('\n');

const system = `You are a senior SEO editor planning a blog article for ${cfg.SITE_URL}.
Business: ${cfg.BUSINESS_DESCRIPTION}
Write all reader-facing text in ${r.language_name}.
Rules:
- The article must fully satisfy the search intent and be clearly better than the current top results: cover what they cover, then add the angle and differentiator.
- Internal links: choose ONLY from the internal page list, exact URLs. Pick pages a reader of this article would genuinely want next. Use descriptive anchor text, never "click here".
- External links: choose ONLY from the external source list, exact URLs. Prefer authority sources. Never link to a page that competes for this keyword.
- Diagrams: plan 1 or 2 diagrams in Mermaid syntax (flowchart TD/LR, sequenceDiagram, timeline, pie or quadrantChart) that explain a process, decision or comparison from the article. Keep node labels short and in ${r.language_name}; wrap labels with special characters in double quotes.
- Answer with JSON only, no prose and no code fences.`;

const user = `Primary keyword: ${r.keyword}
Search intent: ${r.intent} | Volume: ${r.search_volume} | Difficulty: ${r.keyword_difficulty}
Content type: ${r.content_type || 'decide'}
Suggested title: ${r.suggested_title || 'decide'}
Our angle: ${r.angle || 'decide'}
Our differentiator: ${r.differentiator || 'decide'}
Questions the article must answer:
${r.questions.map((q) => `- ${q}`).join('\n')}

Current top results and their headings:
${competitors}

Median competitor length: ${r.competitor_median_words ?? 'unknown'} words. Target length: ${cfg.TARGET_WORDS} words.

Internal page list (url | title | description):
${internalPages}

External source list:
${externalSources || '(none found — leave external_links empty)'}

Return this JSON shape:
{
  "title": "H1, includes the primary keyword, max 65 characters",
  "seo_title": "max 60 characters",
  "meta_description": "max 155 characters, includes the keyword and a reason to click",
  "slug": "lowercase-hyphenated",
  "secondary_keywords": ["string"],
  "search_intent_summary": "one sentence",
  "outline": [
    { "h2": "string", "h3": ["string"], "notes": "what this section must say", "answers_question": "question it answers or empty" }
  ],
  "internal_links": [ { "url": "exact url from the list", "anchor": "string", "section": "h2 where it goes" } ],
  "external_links": [ { "url": "exact url from the list", "anchor": "string", "section": "h2 where it goes", "why": "what it supports" } ],
  "diagrams": [ { "title": "string", "section": "h2 where it goes", "mermaid": "valid mermaid code" } ],
  "faq": [ { "question": "string", "answer_hint": "string" } ],
  "cta": "one sentence call to action that fits the business",
  "featured_image_prompt": "prompt for an illustrative header image, no text in the image"
}
Use ${cfg.MAX_INTERNAL_LINKS} internal links and up to ${cfg.MAX_EXTERNAL_LINKS} external links.`;

return [
	{
		json: {
			anthropic_body: {
				model: cfg.CLAUDE_MODEL,
				max_tokens: 8000,
				system,
				messages: [{ role: 'user', content: user }],
			},
		},
	},
];

// Step 2 of writing: parse the plan, drop any link Claude invented, and ask
// for the full article in Markdown.
const cfg = $('Config').first().json;
const r = $('Research competitors').first().json;

const text = ($input.first().json.content || [])
	.filter((block) => block.type === 'text')
	.map((block) => block.text)
	.join('');
let plan;
try {
	plan = JSON.parse(text.slice(text.indexOf('{'), text.lastIndexOf('}') + 1));
} catch (error) {
	throw new Error(`Outline was not valid JSON. Raw answer starts with: ${text.slice(0, 300)}`);
}

const norm = (u) => String(u || '').trim().replace(/\/+$/, '').toLowerCase();
const internalUrls = new Set(r.internal_pages.map((p) => norm(p.url)));
const externalUrls = new Set(r.external_sources.map((s) => norm(s.url)));

plan.internal_links = (plan.internal_links || []).filter((l) => internalUrls.has(norm(l.url)));
plan.external_links = (plan.external_links || []).filter((l) => externalUrls.has(norm(l.url)));
plan.slug = String(plan.slug || r.keyword)
	.toLowerCase()
	.normalize('NFKD')
	.replace(/[̀-ͯ]/g, '')
	.replace(/[^a-z0-9]+/g, '-')
	.replace(/^-|-$/g, '');

const system = `You are an expert writer for ${cfg.SITE_URL}. Business: ${cfg.BUSINESS_DESCRIPTION}
Brand voice: ${cfg.BRAND_VOICE}
Write in ${r.language_name}.
Rules:
- Follow the outline exactly. Output GitHub-flavoured Markdown only, starting with "# " + the title. No front matter, no code fences around the whole article.
- Open with a 2-3 sentence direct answer to the search intent (featured-snippet style), then a "Key takeaways" bullet list.
- Use the primary keyword in the first 100 words and in at least one H2; use secondary keywords naturally. Never keyword-stuff.
- Place every planned internal and external link exactly once, in its planned section, as [anchor](url). Do not add any other links.
- Insert every planned diagram in its section as a fenced code block with the language "mermaid", preceded by a one-line caption in italics.
- Add at least one Markdown table where a comparison or checklist helps the reader.
- Never invent statistics, studies, quotes or customer names. If a claim needs a number you do not have, write it qualitatively.
- End with an FAQ section (H2) using the planned questions as H3s with short direct answers, then a closing paragraph with the call to action.
- Short paragraphs (max 3 sentences), concrete examples, active voice.`;

const user = `Primary keyword: ${r.keyword}
Target length: about ${cfg.TARGET_WORDS} words.
Angle: ${r.angle}
Differentiator: ${r.differentiator}

Plan:
${JSON.stringify(plan, null, 1)}`;

return [
	{
		json: {
			plan,
			anthropic_body: {
				model: cfg.CLAUDE_MODEL,
				max_tokens: 16000,
				system,
				messages: [{ role: 'user', content: user }],
			},
		},
	},
];

// Quality gate for the draft: removes links that are not in the plan or are
// broken, renders each Mermaid diagram to an image, and builds FAQ schema.
const cfg = $('Config').first().json;
const r = $('Research competitors').first().json;
const plan = $('Build article request').first().json.plan;

let markdown = ($input.first().json.content || [])
	.filter((block) => block.type === 'text')
	.map((block) => block.text)
	.join('')
	.trim()
	.replace(/^```(?:markdown|md)?\s*\n([\s\S]*)\n```$/i, '$1');

const issues = [];
const norm = (u) => String(u || '').trim().replace(/\/+$/, '').toLowerCase();
const siteHost = new URL(cfg.SITE_URL).hostname.replace(/^www\./, '');
const internalUrls = new Set(r.internal_pages.map((p) => norm(p.url)));
const plannedExternal = new Set(plan.external_links.map((l) => norm(l.url)));

const isInternal = (url) => {
	try {
		return new URL(url).hostname.replace(/^www\./, '') === siteHost;
	} catch (error) {
		return false;
	}
};

// 1. Links: keep internal links that exist in the sitemap and external links
// from the plan that still resolve. Anything else becomes plain text.
const linkPattern = /(?<!!)\[([^\]]+)\]\((https?:\/\/[^)\s]+)\)/g;
const externalStatus = new Map();
for (const [, , url] of markdown.matchAll(linkPattern)) {
	if (isInternal(url) || !plannedExternal.has(norm(url)) || externalStatus.has(url)) continue;
	try {
		const res = await this.helpers.httpRequest({
			url,
			method: 'GET',
			timeout: 12000,
			json: false,
			returnFullResponse: true,
			ignoreHttpStatusErrors: true,
			headers: { 'User-Agent': 'Mozilla/5.0 (compatible; BlogAutomationBot/1.0)' },
		});
		// 401/403/429 usually means the site blocks bots, not that the page is gone.
		externalStatus.set(url, res.statusCode < 400 || [401, 403, 429].includes(res.statusCode));
	} catch (error) {
		externalStatus.set(url, false);
	}
}

let internalCount = 0;
let externalCount = 0;
markdown = markdown.replace(linkPattern, (match, anchor, url) => {
	if (isInternal(url)) {
		if (internalUrls.has(norm(url))) {
			internalCount++;
			return match;
		}
		issues.push(`Removed internal link not in sitemap: ${url}`);
		return anchor;
	}
	if (externalStatus.get(url)) {
		externalCount++;
		return match;
	}
	issues.push(`Removed external link (not planned or broken): ${url}`);
	return anchor;
});

// 2. Diagrams: render each mermaid block with mermaid.ink. A diagram that
// does not render (syntax error) is removed rather than published broken.
const diagrams = [];
const blocks = [...markdown.matchAll(/```mermaid\s*\n([\s\S]*?)```/g)];
let markdownForCms = markdown;
for (const [index, block] of blocks.entries()) {
	const code = block[1].trim();
	const encoded = Buffer.from(code, 'utf8').toString('base64url');
	const pngUrl = `https://mermaid.ink/img/${encoded}?type=png&bgColor=!white&width=1200`;
	const svgUrl = `https://mermaid.ink/svg/${encoded}`;
	const title = plan.diagrams?.[index]?.title || `${r.keyword} diagram ${index + 1}`;
	let renders = false;
	try {
		const res = await this.helpers.httpRequest({
			url: svgUrl,
			timeout: 20000,
			json: false,
			returnFullResponse: true,
			ignoreHttpStatusErrors: true,
		});
		renders = res.statusCode === 200;
	} catch (error) {
		renders = false;
	}
	if (renders) {
		diagrams.push({ title, mermaid: code, png_url: pngUrl, svg_url: svgUrl });
		markdownForCms = markdownForCms.replace(block[0], `![${title.replace(/[\[\]]/g, '')}](${pngUrl})`);
	} else {
		issues.push(`Diagram "${title}" did not render and was removed.`);
		markdownForCms = markdownForCms.replace(block[0], '');
		markdown = markdown.replace(block[0], '');
	}
}

// 3. FAQ schema from the "FAQ" H2 section: every H3 is a question.
const faqSection = markdown.split(/\n## /).find((s) => /^(faq|veelgestelde vragen|frequently asked questions|veel gestelde vragen)/i.test(s.trim()));
const faq = faqSection
	? [...faqSection.matchAll(/\n### (.+)\n+([\s\S]*?)(?=\n### |\n## |$)/g)].map((m) => ({
			'@type': 'Question',
			name: m[1].trim(),
			acceptedAnswer: { '@type': 'Answer', text: m[2].replace(/\[([^\]]+)\]\([^)]+\)/g, '$1').trim() },
		}))
	: [];
const faqSchema = faq.length
	? JSON.stringify({ '@context': 'https://schema.org', '@type': 'FAQPage', mainEntity: faq })
	: '';

const wordCount = markdown.replace(/```[\s\S]*?```/g, '').split(/\s+/).filter(Boolean).length;
if (internalCount < 2) issues.push(`Only ${internalCount} internal links made it into the article.`);
if (wordCount < Number(cfg.TARGET_WORDS) * 0.7) issues.push(`Article is short: ${wordCount} words.`);

return [
	{
		json: {
			keyword: r.keyword,
			title: plan.title,
			seo_title: plan.seo_title,
			meta_description: plan.meta_description,
			slug: plan.slug,
			secondary_keywords: (plan.secondary_keywords || []).join(' | '),
			markdown,
			markdown_for_cms: markdownForCms,
			diagram_urls: diagrams.map((d) => d.png_url).join(' | '),
			diagrams_mermaid: diagrams.map((d) => `%% ${d.title}\n${d.mermaid}`).join('\n\n'),
			faq_schema: faqSchema,
			featured_image_prompt: plan.featured_image_prompt || '',
			word_count: wordCount,
			internal_links: internalCount,
			external_links: externalCount,
			issues: issues.join(' | '),
			status: issues.length ? 'needs-review' : 'draft-ready',
			created_at: new Date().toISOString(),
		},
	},
];

// Marks the keyword as written so the next run picks a new one.
const post = $input.first().json;
return [{ json: { keyword: post.keyword, status: 'drafted', post_slug: post.slug } }];

// Turns the backlinks of the best-ranking competitor page into an outreach
// list: sites that already link to this topic and may link to our article.
const r = $('Research competitors').first().json;
const post = $('Finalize draft').first().json;

let backlinks = [];
try {
	backlinks = $('DataForSEO: Competitor backlinks')
		.all()
		.flatMap((i) => i.json.tasks || [])
		.flatMap((t) => t.result || [])
		.flatMap((res) => res.items || []);
} catch (error) {
	backlinks = [];
}

if (!backlinks.length) return [];

return backlinks.slice(0, 50).map((b) => ({
	json: {
		keyword: r.keyword,
		our_post_slug: post.slug,
		competitor_url: b.url_to,
		linking_page: b.url_from,
		linking_domain: b.domain_from,
		linking_page_title: b.page_from_title || '',
		anchor: b.anchor || '',
		domain_rank: b.domain_from_rank ?? '',
		dofollow: b.dofollow ? 'yes' : 'no',
		outreach_status: 'todo',
		found_at: new Date().toISOString(),
	},
}));
